style.css:
@-moz-document url-prefix("") {
html, body {
    background: linear-gradient(135deg, #0a1f0a 0%, #123a12 25%, #1e5c1e 50%, #2e8b2e 75%, #39a939 100%) !important;
    background-attachment: fixed !important;
    color: #d4ffcc !important;
  }

  /* Основные контейнеры/обёртки */
  div, section, article, main, aside, header, footer, nav {
    background-color: transparent !important;
    color: #d4ffcc !important;
  }

  /* Ссылки */
  a, a:visited {
    color: #7fff00 !important;
  }
  a:hover {
    color: #adff2f !important;
    text-shadow: 0 0 5px #7fff00 !important;
  }

  /* Заголовки */
  h1, h2, h3, h4, h5, h6 {
    color: #baff29 !important;
    text-shadow: 0 0 3px rgba(127, 255, 0, 0.4) !important;
  }

  /* Кнопки и инпуты */
  button, input, select, textarea {
    background: linear-gradient(135deg, #1e5c1e, #39a939) !important;
    color: #eaffea !important;
    border: 1px solid #7fff00 !important;
  }

  /* Скроллбар (в браузерах на Webkit/Blink) */
  ::-webkit-scrollbar {
    width: 10px !important;
  }
  ::-webkit-scrollbar-track {
    background: #0a1f0a !important;
  }
  ::-webkit-scrollbar-thumb {
    background: linear-gradient(#39a939, #123a12) !important;
    border-radius: 5px !important;
  }

  /* Выделение текста */
  ::selection {
    background: #7fff00 !important;
    color: #0a1f0a !important;
  }
}
